const lowerDictionary = new Map();
for (const [en, zh] of Object.entries(DICTIONARY)) {
  lowerDictionary.set(en.toLowerCase(), zh);
}

export function looksLikePathOrId(text) {
  const s = String(text || '').trim();
  if (!s) return false;
  if (/^(https?:\/\/|file:\/\/)/i.test(s) || /^[\w.-]+\.[a-z]{2,}([/:?#]|$)/i.test(s)) return true;
  if (/^[A-Za-z]:[\\/]/.test(s) || /^\\\\/.test(s)) return true;
  if (/(^|[\s])(\/[\w.-]+){2,}/.test(s)) return true;
  if (/^~\/[\w./-]+/.test(s)) return true;
  if (/^[0-9a-f]{7,40}$/i.test(s)) return true;
  if (/^[a-z0-9._-]+\/[a-z0-9._/-]+$/i.test(s) && !/\s/.test(s)) return true; // branch or repo
  if (/^sha256:[0-9a-f]+$/i.test(s)) return true;
  if (/^[\w.+-]+@[\w.-]+\.[a-z]{2,}$/i.test(s)) return true;
  return false;
}

export function looksLikeShortcut(text) {
  const s = String(text || '').trim();
  if (!s) return false;
  if (/^\d+\s*%$/.test(s)) return true;
  return /^(?:(?:Ctrl|Control|Cmd|Command|Alt|Option|Shift|Meta|Win|Super)\s*\+\s*)+(?:[A-Za-z0-9]|F\d{1,2}|Enter|Tab|Space|Esc|Escape|Backspace|Delete|Home|End|Insert|PageUp|PageDown|\[|\]|\\|;|'|,|\.|\/|`|-|=)$/i.test(s);
}

const GREETING_HEADS = {
  'Welcome back': '欢迎回来',
  'Welcome': '欢迎',
  'Good morning': '早上好',
  'Good afternoon': '下午好',
  'Good evening': '晚上好',
  'Hey': '你好',
  'Hi': '你好',
  'Hello': '你好'
};

const GREETING_TAILS = {
  'Where should we pick up?': '从哪里继续？',
  'What would you like to work on?': '你想做些什么？',
  'What are we building today?': '今天我们要构建什么？',
  'What should we build today?': '今天我们做点什么？',
  'How can I help today?': '今天我能帮你什么？',
  'Ready to get started?': '准备好开始了吗？'
};

const GREETING_HEAD_RE = 'Welcome back|Good morning|Good afternoon|Good evening|Welcome|Hello|Hey|Hi';
const INFORMAL_HEAD_RE = 'Hello|Hey|Hi';
const GREETING_TAIL_RE = 'Where should we pick up\\?|What would you like to work on\\?|What are we building today\\?|What should we build today\\?|How can I help today\\?|Ready to get started\\?';

function isSafeGreetingName(name) {
  const n = String(name || '').trim();
  if (!n || n.length > 80) return false;
  if (looksLikePathOrId(n) || looksLikeShortcut(n)) return false;
  if (/https?:\/\//i.test(n) || /[\\/]/.test(n) || /@/.test(n)) return false;
  return true;
}

function pickGreetingHead(raw) {
  const key = Object.keys(GREETING_HEADS).find((k) => k.toLowerCase() === String(raw).toLowerCase());
  return key ? GREETING_HEADS[key] : null;
}

function pickGreetingTail(raw) {
  const key = Object.keys(GREETING_TAILS).find((k) => k.toLowerCase() === String(raw).toLowerCase());
  return key ? GREETING_TAILS[key] : null;
}

function swapTrimmed(original, trimmed, next) {
  const start = original.indexOf(trimmed);
  if (start < 0) return next;
  let end = start + trimmed.length;
  if (/[，。]$/.test(next)) {
    while (end < original.length && /\s/.test(original.charAt(end))) end += 1;
  }
  return original.slice(0, start) + next + original.slice(end);
}

export function applyGreetingRules(text) {
  const original = String(text ?? '');
  const trimmed = original.trim();
  if (!trimmed) return original;

  const informalFull = trimmed.match(new RegExp('^(' + INFORMAL_HEAD_RE + ')\\s+(.+?),\\s+(' + GREETING_TAIL_RE + ')$', 'i'));
  if (informalFull && isSafeGreetingName(informalFull[2])) {
    const head = pickGreetingHead(informalFull[1]);
    const tail = pickGreetingTail(informalFull[3]);
    if (head && tail) return swapTrimmed(original, trimmed, head + '，' + informalFull[2].trim() + '，' + tail);
  }

  const informalNamed = trimmed.match(new RegExp('^(' + INFORMAL_HEAD_RE + ')\\s+(.+?),\\s*$', 'i'));
  if (informalNamed && isSafeGreetingName(informalNamed[2]) && !new RegExp('^(' + GREETING_TAIL_RE + ')$', 'i').test(informalNamed[2].trim())) {
    const head = pickGreetingHead(informalNamed[1]);
    if (head) return swapTrimmed(original, trimmed, head + '，' + informalNamed[2].trim() + '，');
  }

  const informalHeadOnly = trimmed.match(new RegExp('^(' + INFORMAL_HEAD_RE + '),?\\s*$', 'i'));
  if (informalHeadOnly) {
    const head = pickGreetingHead(informalHeadOnly[1]);
    if (head) return swapTrimmed(original, trimmed, head + '，');
  }

  const informalTail = trimmed.match(new RegExp('^,\\s*(' + GREETING_TAIL_RE + ')$', 'i'));
  if (informalTail) {
    const tail = pickGreetingTail(informalTail[1]);
    if (tail) return swapTrimmed(original, trimmed, '，' + tail);
  }

  const full = trimmed.match(new RegExp('^(' + GREETING_HEAD_RE + '),\\s+(.+?)\\.\\s+(' + GREETING_TAIL_RE + ')$', 'i'));
  if (full && isSafeGreetingName(full[2])) {
    const head = pickGreetingHead(full[1]);
    const tail = pickGreetingTail(full[3]);
    if (head && tail) return swapTrimmed(original, trimmed, head + '，' + full[2].trim() + '。' + tail);
  }

  const named = trimmed.match(new RegExp('^(' + GREETING_HEAD_RE + '),\\s+(.+?)\\.?$', 'i'));
  if (named && isSafeGreetingName(named[2]) && !new RegExp('^(' + GREETING_TAIL_RE + ')$', 'i').test(named[2].trim())) {
    const head = pickGreetingHead(named[1]);
    if (head) return swapTrimmed(original, trimmed, head + '，' + named[2].trim() + '。');
  }

  const headOnly = trimmed.match(new RegExp('^(' + GREETING_HEAD_RE + '),\\s*$', 'i'));
  if (headOnly) {
    const head = pickGreetingHead(headOnly[1]);
    if (head) return swapTrimmed(original, trimmed, head + '，');
  }

  const tailOnly = trimmed.match(new RegExp('^\\.?\\s*(' + GREETING_TAIL_RE + ')$', 'i'));
  if (tailOnly) {
    const tail = pickGreetingTail(tailOnly[1]);
    if (tail) {
      const hadDot = /^\./.test(trimmed);
      return swapTrimmed(original, trimmed, (hadDot ? '。' : '') + tail);
    }
  }

  return original;
}

function lookupDictionary(trimmed) {
  if (!trimmed) return null;
  if (Object.prototype.hasOwnProperty.call(DICTIONARY, trimmed)) return DICTIONARY[trimmed];
  const collapsed = trimmed.replace(/\s+/g, ' ');
  if (collapsed !== trimmed && Object.prototype.hasOwnProperty.call(DICTIONARY, collapsed)) return DICTIONARY[collapsed];
  if (trimmed.length >= 3) {
    const lower = lowerDictionary.get(trimmed.toLowerCase());
    if (lower) return lower;
    if (collapsed !== trimmed) {
      const lowerCollapsed = lowerDictionary.get(collapsed.toLowerCase());
      if (lowerCollapsed) return lowerCollapsed;
    }
  }
  return null;
}

export function looksLikeProse(text) {
  const s = String(text || '').trim();
  if (s.length >= 180 && !DICTIONARY[s] && !lowerDictionary.has(s.toLowerCase())) {
    const words = s.split(/\s+/).length;
    if (words >= 18) return true;
  }
  return false;
}

export function shouldSkipElement(el) {
  if (!el) return true;
  if (el.nodeType === 3) el = el.parentElement;
  if (!el || !el.closest) return false;
  if (el.closest(SKIP_SELECTOR)) return true;
  const al = el.getAttribute && el.getAttribute('aria-label');
  if (al === 'File path breadcrumbs' || (el.closest && el.closest('[aria-label="File path breadcrumbs"]'))) {
    return true;
  }
  const testid = (el.getAttribute && (el.getAttribute('data-testid') || '')) || '';
  if (/user-input|assistant-message|markdown|composer-input|chat-input/i.test(testid)) return true;
  return false;
}

export function isIsolatedUiControl(el) {
  if (!el || !el.matches) return false;
  return el.matches(SAFE_PLACEHOLDER_SELECTOR + ', [role="cell"], th, td, dt, dd, legend, figcaption, .menu-item, .tab, nav, header, footer, [role="menubar"], [role="toolbar"]');
}

function formatDuration(raw) {
  return String(raw)
    .replace(/(\d+)\s*d(?:ays?)?/gi, '$1天 ')
    .replace(/(\d+)\s*h(?:ours?)?/gi, '$1小时 ')
    .replace(/(\d+)\s*m(?:inutes?|ins?)?/gi, '$1分钟 ')
    .replace(/(\d+)\s*s(?:econds?|ecs?)?/gi, '$1秒 ')
    .replace(/,/g, ' ')
    .trim();
}


