export function looksLikeCompositeEmptyState(text) {
  const t = String(text || '').replace(/\s+/g, ' ').trim();
  return /^No\s+.+\s+yet\.?$/i.test(t) || /^No\s+.+\s+match\s+[\u201c"'].+[\u201d"']\.?$/i.test(t);
}

export function applyEmptyStateRules(text) {
  const original = String(text ?? '');
  const trimmed = original.trim();
  if (!trimmed) return original;

  let m = trimmed.match(/^No\s+(.+?)\s+yet\.?$/i);
  if (m) {
    const key = m[1].replace(/\s+/g, ' ').trim().replace(/\.$/, '').toLowerCase();
    const zh = EMPTY_STATE_NOUNS[key];
    if (zh) return original.replace(trimmed, zh);
  }

  m = trimmed.match(/^No\s+(.+?)\s+match\s+[\u201c"'](.+?)[\u201d"']\.?$/i);
  if (m) {
    const key = m[1].replace(/\s+/g, ' ').trim().toLowerCase();
    const noun = EMPTY_STATE_MATCH_NOUNS[key] || m[1];
    return original.replace(trimmed, '没有与“' + m[2] + '”匹配的' + noun);
  }
  return original;
}

export function applyRegexRules(text) {
  const trimmed = text.trim();
  let m;

  if (text.includes('of the customization budget is available')) {
    text = text.replace(/(\d+(?:\.\d+)?)%\s*of the customization budget is available\.?/g, '自定义项预算可用额度为 $1%。');
    text = text.replace(/%\s*of the customization budget is available\.?/g, '% 的自定义项预算可用额度。');
  }

  if ((m = trimmed.match(/^Show (\d+) breakdowns?$/i))) {
    return text.replace(trimmed, '显示 ' + m[1] + ' 项明细');
  }
  if ((m = trimmed.match(/^Explored (\d+) files?\s*>?$/i))) {
    return text.replace(trimmed, '已浏览 ' + m[1] + ' 个文件' + (/>$/.test(trimmed) ? ' >' : ''));
  }
  if ((m = trimmed.match(/^Edited (\d+) files?$/i))) {
    return text.replace(trimmed, '已编辑 ' + m[1] + ' 个文件');
  }
  if ((m = trimmed.match(/^Ran (\d+) commands?$/i))) {
    return text.replace(trimmed, '已运行 ' + m[1] + ' 条命令');
  }
  if ((m = trimmed.match(/^Editing (.+) \+(\d+) -(\d+)$/))) {
    return text.replace(trimmed, '正在编辑 ' + m[1] + ' +' + m[2] + ' -' + m[3]);
  }
  if ((m = trimmed.match(/^Artifacts?\s+(\d+)$/i))) {
    return text.replace(trimmed, '产物 ' + m[1]);
  }
  if (/^Waiting for user input$/i.test(trimmed)) {
    return text.replace(trimmed, '等待用户输入');
  }
  if ((m = trimmed.match(/^(?:No|否)\s+projects?\s+found\.?$/i)) || trimmed === 'No projects found') {
    return text.replace(trimmed, '暂无项目');
  }
  if (/^No\s+Project$/i.test(trimmed)) {
    return text.replace(trimmed, '无项目');
  }
  if ((m = trimmed.match(/^Finish signing in to(?:\s+(.+?))?(?:\s+in your browser\.)?$/i))) {
    const name = (m[1] || '').trim();
    if (name && /in your browser\.$/i.test(trimmed)) {
      return text.replace(trimmed, '请在浏览器中完成 ' + name + ' 的登录。');
    }
    if (name) return text.replace(trimmed, '完成 ' + name + ' 的登录');
    return text.replace(trimmed, '完成登录');
  }
  if ((m = trimmed.match(/^Included by\s+(.+)$/i))) {
    return text.replace(trimmed, '包含于 ' + m[1]);
  }
  if ((m = trimmed.match(/^Installed in\s+(.+)$/i))) {
    return text.replace(trimmed, '安装于 ' + m[1]);
  }
  if ((m = trimmed.match(/^No MCP servers found for\s+[\u201c"'](.+?)[\u201d"']$/i))) {
    return text.replace(trimmed, '没有找到与“' + m[1] + '”匹配的 MCP 服务器');
  }
  if ((m = trimmed.match(/^Are you sure you want to delete the hook "(.+)"\?$/i))) {
    return text.replace(trimmed, '确定要删除钩子“' + m[1] + '”吗？');
  }
  if ((m = trimmed.match(/^(\d+) MCP servers failed to start$/i))) {
    return text.replace(trimmed, m[1] + ' 个 MCP 服务器启动失败');
  }
  if ((m = trimmed.match(/^Failed to (load|read|save|write) hooks\.json:\s*(.*)$/i))) {
    const verb = { load: '加载', read: '读取', save: '保存', write: '写入' }[m[1].toLowerCase()];
    return text.replace(trimmed, '无法' + verb + ' hooks.json：' + (m[2] || ''));
  }
  if ((m = trimmed.match(/^Failed to fetch available MCP servers:\s*(.*)$/i))) {
    return text.replace(trimmed, '无法获取可用的 MCP 服务器：' + (m[1] || ''));
  }
  if ((m = trimmed.match(/^\+?\s*See (\d+) more$/i))) {
    return text.replace(trimmed, '查看另外 ' + m[1] + ' 个');
  }
  if ((m = trimmed.match(/^Learn more about (.+)$/i))) {
    const inner = translateText(m[1], { isolated: true });
    return text.replace(trimmed, '了解更多关于 ' + inner + ' 的信息');
  }
  if ((m = trimmed.match(/^You have used some of your weekly limit, it will fully refresh in (.*)\.?$/i))) {
    return text.replace(trimmed, '您已使用部分每周限额，将在 ' + formatDuration(m[1]) + ' 后完全重置。');
  }
  if ((m = trimmed.match(/^You have used some of your 5-hour limit, it will fully refresh in (.*)\.?$/i))) {
    return text.replace(trimmed, '您已使用部分五小时限额，将在 ' + formatDuration(m[1]) + ' 后完全重置。');
  }
  if ((m = trimmed.match(/^Resets? in\s+(.+)$/i))) {
    return text.replace(trimmed, '将在 ' + formatDuration(m[1]) + ' 后重置');
  }
  if ((m = trimmed.match(/^(\d+)\s+agents? running$/i))) {
    return text.replace(trimmed, m[1] === '0' || trimmed.toLowerCase().startsWith('no ')
      ? '没有正在运行的智能体'
      : '正在运行 ' + m[1] + ' 个智能体');
  }
  if (/^No agents running$/i.test(trimmed)) {
    return text.replace(trimmed, '没有正在运行的智能体');
  }
  if (text.includes('Worked for')) {
    return text.replace(/Worked for ([\d.a-z ]+)/gi, (_, timeStr) => {
      const t = timeStr.replace(/ms/g, '毫秒').replace(/s/g, '秒').replace(/m/g, '分').replace(/h/g, '小时');
      return '运行耗时 ' + t;
    });
  }
  if (text.includes('Thought for')) {
    return text.replace(/Thought for ([\d.a-z ]+)/gi, (_, timeStr) => {
      const t = timeStr.replace(/ms/g, '毫秒').replace(/s/g, '秒').replace(/m/g, '分').replace(/h/g, '小时');
      return '思考耗时 ' + t;
    });
  }
  if ((m = trimmed.match(/^(.+) wants to connect to a (HID device|USB device|serial port)$/))) {
    const kind = DICTIONARY[m[2]] || m[2];
    return text.replace(trimmed, m[1] + ' 想要连接' + kind);
  }
  if ((m = trimmed.match(/^Installing into (.+)…$/))) {
    return text.replace(trimmed, '正在安装到 ' + m[1] + '…');
  }
  if ((m = trimmed.match(/^Setting up WSL:\s*(.+)$/))) {
    return text.replace(trimmed, '正在设置 WSL：' + m[1]);
  }
  if ((m = trimmed.match(/^The WSL distro "(.+)" is no longer installed\.$/))) {
    return text.replace(trimmed, 'WSL 发行版“' + m[1] + '”已不再安装。');
  }
  if ((m = trimmed.match(/^Restarting the Antigravity server on (.+)…$/))) {
    return text.replace(trimmed, '正在重启 ' + m[1] + ' 上的 Antigravity 服务器…');
  }
  if ((m = trimmed.match(/^Reconnecting to (.+)…$/))) {
    return text.replace(trimmed, '正在重新连接到 ' + m[1] + '…');
  }
  if ((m = trimmed.match(/^Disconnected from (.+)$/))) {
    return text.replace(trimmed, '已从 ' + m[1] + ' 断开连接');
  }
  if ((m = trimmed.match(/^Agents keep running on (.+)\.$/))) {
    return text.replace(trimmed, '智能体仍在 ' + m[1] + ' 上运行。');
  }
  if ((m = trimmed.match(/^Agents keep running on (.+) unless its server stopped\.$/))) {
    return text.replace(trimmed, '除非其服务器已停止，智能体仍在 ' + m[1] + ' 上运行。');
  }
  if ((m = trimmed.match(/^Its server on (.+) stopped, and its agents with it\.$/))) {
    return text.replace(trimmed, m[1] + ' 上的服务器已停止，其上的智能体也已停止。');
  }
  if ((m = trimmed.match(/^Its agents on (.+) stopped with it\.$/))) {
    return text.replace(trimmed, m[1] + ' 上的智能体已随其一同停止。');
  }
  if ((m = trimmed.match(/^Connecting to\s*(.*)$/))) {
    return text.replace(trimmed, '正在连接到' + (m[1] ? ' ' + m[1] : ''));
  }
  if ((m = trimmed.match(/^(\d+)\s+matches?$/i))) {
    return text.replace(trimmed, m[1] + ' 处匹配');
  }
  return text;
}


const LEGAL_NOTICE_BODY_EN = 'Google does not control the availability or functionality of third party developer tools. Your data from third party developer tools connected to your Antigravity instance may be shared with Google. Google will protect any such data in accordance with the Google Privacy Policy, found here';
export const LEGAL_NOTICE_ZH = 'Google 并不控制第三方开发者工具的可用性或功能。连接到你的 Antigravity 实例的第三方开发者工具中的数据可能会与 Google 共享。Google 将按照 Google 隐私权政策保护此类数据，该政策详见：';
const PRIVACY_POLICY_HREF_RE = /^https?:\/\/policies\.google\.com\/privacy\/?$/i;
const LEGAL_NOTICE_BANNED_TAGS = new Set(['BUTTON', 'INPUT', 'TEXTAREA', 'SELECT', 'IMG', 'VIDEO', 'SVG', 'CANVAS', 'IFRAME', 'CODE', 'PRE']);

function nodeTextContent(node) {
  if (!node) return '';
  if (node.nodeType === 3) return node.textContent == null ? '' : String(node.textContent);
  if (typeof node.textContent === 'string' && !(node.childNodes && node.childNodes.length)) return node.textContent;
  const kids = node.childNodes || [];
  let s = '';
  for (let i = 0; i < kids.length; i++) s += nodeTextContent(kids[i]);
  if (s) return s;
  return node.textContent == null ? '' : String(node.textContent);
}

function isPrivacyPolicyAnchor(el) {
  if (!el || String(el.tagName || '').toUpperCase() !== 'A') return false;
  const href = ((el.getAttribute && el.getAttribute('href')) || el.href || '').trim();
  return PRIVACY_POLICY_HREF_RE.test(href);
}

export function isLegalNoticeText(text) {
  let collapsed = String(text || '').replace(/\s+/g, ' ').trim();
  if (!collapsed || !/third party developer tools/i.test(collapsed)) return false;
  collapsed = collapsed.replace(/\s+(https?:\/\/policies\.google\.com\/privacy\/?)\.?$/i, '');
  collapsed = collapsed.replace(/[:：.\s]+$/, '');
  return collapsed.toLowerCase() === LEGAL_NOTICE_BODY_EN.toLowerCase();
}

export function applyLegalNoticeRules(text) {
  const original = String(text ?? '');
  const trimmed = original.trim();
  if (!isLegalNoticeText(trimmed)) return original;
  const collapsed = trimmed.replace(/\s+/g, ' ');
  const um = collapsed.match(/\s+(https?:\/\/policies\.google\.com\/privacy\/?)\.?$/i);
  const zh = um ? LEGAL_NOTICE_ZH + um[1].replace(/\/$/, '') : LEGAL_NOTICE_ZH;
  return swapTrimmed(original, trimmed, zh);
}

function legalNoticeShapeOk(el) {
  if (!el) return false;
  let ok = true;
  function walk(node) {
    if (!ok || !node) return;
    if (node.nodeType !== 1) return;
    const tag = String(node.tagName || '').toUpperCase();
    if (LEGAL_NOTICE_BANNED_TAGS.has(tag)) {
      ok = false;
      return;
    }
    if (tag === 'A' && !isPrivacyPolicyAnchor(node)) {
      ok = false;
      return;
    }
    const kids = node.childNodes || [];
    for (let i = 0; i < kids.length; i++) walk(kids[i]);
  }
  const kids = el.childNodes || [];
  for (let i = 0; i < kids.length; i++) walk(kids[i]);
  return ok;
}

export function rewriteCompositeLegalNotice(el) {
  if (!el || shouldSkipElement(el)) return false;
  if (!legalNoticeShapeOk(el)) return false;
  const combined = nodeTextContent(el);
  if (!isLegalNoticeText(combined)) return false;

  const textNodes = [];
  function collect(node) {
    if (!node) return;
    if (node.nodeType === 3) {
      const parentTag = String((node.parentElement && node.parentElement.tagName) || '').toUpperCase();
      if (parentTag !== 'A') textNodes.push(node);
      return;
    }
    if (node.nodeType === 1 && String(node.tagName || '').toUpperCase() === 'A') return;
    const kids = node.childNodes || [];
    for (let i = 0; i < kids.length; i++) collect(kids[i]);
  }
  collect(el);

  if (!textNodes.length) return false;
  let assigned = false;
  for (const n of textNodes) {
    const raw = n.textContent == null ? '' : String(n.textContent);
    if (!assigned && raw.replace(/\s+/g, ' ').trim()) {
      const leading = (raw.match(/^\s*/) || [''])[0];
      n.textContent = leading + LEGAL_NOTICE_ZH;
      assigned = true;
    } else {
      n.textContent = '';
    }
  }
  return assigned;
}

export function translateText(text, options = {}) {
  if (text == null) return text;
  const original = String(text);
  if (!/[A-Za-z]/.test(original)) return original;
  if (looksLikePathOrId(original)) return original;
  if (looksLikeShortcut(original)) return original;

  const trimmed = original.trim();
  if (!trimmed) return original;

  const exact = lookupDictionary(trimmed);
  if (exact) return original.replace(trimmed, exact);

  const afterGreeting = applyGreetingRules(original);
  if (afterGreeting !== original) return afterGreeting;

  const afterEmpty = applyEmptyStateRules(original);
  if (afterEmpty !== original) return afterEmpty;

  const afterLegal = applyLegalNoticeRules(original);
  if (afterLegal !== original) return afterLegal;

  const afterRegex = applyRegexRules(original);
  if (afterRegex !== original) return afterRegex;

  for (const [en, zh] of PREFIX_RULES) {
    if (trimmed.includes(en)) return zh;
  }

  if (looksLikeProse(original) && !options.allowProse) {
    return original;
  }

  const wordCount = trimmed.split(/\s+/).length;
  if (wordCount <= 3 && options.isolated === true) {
    const hit = CORE_WORDS[trimmed.toLowerCase()];
    if (hit) return original.replace(trimmed, hit);
  }
  return original;
}

export function shouldTranslatePlaceholder(el) {
  if (!el) return false;
  if (el.closest && el.closest('[data-ag-localization-skip]')) return false;
  const tag = (el.tagName || '').toLowerCase();
  if (tag === 'input' || tag === 'textarea') return true; // placeholder only, not value
  return isIsolatedUiControl(el);
}

export { SKIP_SELECTOR, SAFE_PLACEHOLDER_SELECTOR };
